#!/bin/sh
# clangcheck.sh FILE... : clang MSVC-like warnings on the lines added vs master (run from PowerEditor/gcc of a checkout)
for f in "$@"; do
  added=$(git diff -U0 master -- "$f" | awk '/^@@/ { split($3, a, ","); s=substr(a[1],2); n=(a[2]==""?1:a[2]); for (i=s;i<s+n;i++) print i }')
  clang++ --target=x86_64-w64-mingw32 -include ../gcc/gcc-fixes.h  -std=c++20 -Wpedantic -Wall -Wextra -Wconversion  -Wno-cast-function-type -Wno-overloaded-virtual -Wno-system-headers -isystem ../src/json -isystem ../src/pugixml -isystem ../src/uchardet -isystem ../src/MISC/crc16 -isystem ../src/MISC/md5 -isystem ../src/MISC/sha1 -isystem ../src/MISC/sha2 -isystem ../src/MISC/sha512 -isystem ../src/MISC/hmac -isystem ../../scintilla/include -isystem ../../lexilla/include  -I../../scintilla/include -I../../lexilla/include -I../src/. -I../src/DarkMode -I../src/MISC -I../src/MISC/Common -I../src/MISC/Exception -I../src/MISC/PluginsManager -I../src/MISC/Process -I../src/MISC/RegExt -I../src/MISC/crc16 -I../src/MISC/hmac -I../src/MISC/md5 -I../src/MISC/sha1 -I../src/MISC/sha2 -I../src/MISC/sha512 -I../src/ScintillaComponent -I../src/WinControls -I../src/WinControls/AboutDlg -I../src/WinControls/AnsiCharPanel -I../src/WinControls/ClipboardHistory -I../src/WinControls/ColourPicker -I../src/WinControls/ContextMenu -I../src/WinControls/DockingWnd -I../src/WinControls/DocumentMap -I../src/WinControls/DoubleBuffer -I../src/WinControls/FileBrowser -I../src/WinControls/FindCharsInRange -I../src/WinControls/FunctionList -I../src/WinControls/Grid -I../src/WinControls/ImageListSet -I../src/WinControls/OpenSaveFileDialog -I../src/WinControls/PluginsAdmin -I../src/WinControls/Preference -I../src/WinControls/ProjectPanel -I../src/WinControls/ReadDirectoryChanges -I../src/WinControls/SplitterContainer -I../src/WinControls/StaticDialog -I../src/WinControls/StaticDialog/RunDlg -I../src/WinControls/StatusBar -I../src/WinControls/TabBar -I../src/WinControls/TaskList -I../src/WinControls/ToolBar -I../src/WinControls/ToolTip -I../src/WinControls/TrayIcon -I../src/WinControls/TreeView -I../src/WinControls/VerticalFileSwitcher -I../src/WinControls/WindowsDlg -I../src/WinControls/shortcut -I../src/json -I../src/pugixml -I../src/uchardet -DUNICODE -D_UNICODE -DOEMRESOURCE -DNOMINMAX -D_WIN32_WINNT=_WIN32_WINNT_WIN7 -DNTDDI_VERSION=NTDDI_WIN7 -DNDEBUG -DSTRSAFE_NO_DEPRECATE  -Wno-everything -Wshadow-all -Wsign-compare -Wunreachable-code -Wunused -Wimplicit-int-conversion -Wshorten-64-to-32 -Wimplicit-fallthrough -Wunused-lambda-capture -fsyntax-only "$f" 2>&1 | grep -E "^$f:[0-9]+:[0-9]+: warning" | while IFS=: read file line col rest; do echo "$added" | grep -qx "$line" && echo "$file:$line:$rest"; done
done
